// Package gen turns a scan.Result into the source of trilha_gen.go.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
	"text/template"

	"github.com/emersonjoe/trilha/internal/scan"
)

// FileName is the generated file's name at the project root.
const FileName = "trilha_gen.go"

// RuntimeImport is the import path of the trilha runtime.
const RuntimeImport = "github.com/emersonjoe/trilha"

var tmpl = template.Must(template.New("gen").Funcs(template.FuncMap{
	"refs":  refList,
	"quote": func(s string) string { return fmt.Sprintf("%q", s) },
}).Parse(`// Code generated by trilha. DO NOT EDIT.

package main

import (
{{- if .HasPublic}}
	"embed"
{{- end}}

	trilha "{{.Runtime}}"
{{- range .Imports}}
	{{.Alias}} "{{.Path}}"
{{- end}}
)
{{if .HasPublic}}
//go:embed public
var publicFS embed.FS
{{end}}
// newApp builds the application. Tests can call it and use a.Handler().
func newApp() *trilha.App {
	cfg := trilha.ConfigFromEnv()
{{- if .HasPublic}}
	cfg.Public = trilha.PublicFS(publicFS, "public")
{{- else}}
	cfg.Public = trilha.PublicFS(nil, "public")
{{- end}}
{{- if .ConfigFunc}}
	{{.ConfigFunc.Alias}}.{{.ConfigFunc.Func}}(&cfg)
{{- end}}
	a := trilha.New(cfg)
{{- if .Setup}}
	if err := {{.Setup.Alias}}.{{.Setup.Func}}(a); err != nil {
		trilha.Fatal(err)
	}
{{- end}}
{{- if .RootLayout}}
	a.SetRootLayout({{.RootLayout.Alias}}.{{.RootLayout.Func}})
{{- end}}
{{- if .NotFound}}
	a.SetNotFound({{.NotFound.Alias}}.{{.NotFound.Func}})
{{- end}}
{{- if .ErrorPage}}
	a.SetErrorPage({{.ErrorPage.Alias}}.{{.ErrorPage.Func}})
{{- end}}
{{- range .Routes}}
{{- $r := .}}
	a.Register(trilha.Route{
		Pattern: {{quote .Pattern}},
{{- if .HasPage}}
		Page: {{.Alias}}.Page,
{{- end}}
{{- if .Methods}}
		Methods: map[string]trilha.HandlerFunc{
{{- range .Methods}}
			{{quote .}}: {{$r.Alias}}.{{.}},
{{- end}}
		},
{{- end}}
{{- if .Layouts}}
		Layouts: []trilha.LayoutFunc{ {{refs .Layouts}} },
{{- end}}
{{- if .Middlewares}}
		Middlewares: []trilha.MiddlewareFunc{ {{refs .Middlewares}} },
{{- end}}
	})
{{- end}}
	return a
}

func main() {
	trilha.Run(newApp())
}
`))

func refList(rs []scan.Ref) string {
	parts := make([]string, len(rs))
	for i, r := range rs {
		parts[i] = r.Alias + "." + r.Func
	}
	return strings.Join(parts, ", ")
}

type routeView struct {
	scan.Route
	Alias string
}

type view struct {
	*scan.Result
	Runtime string
	Routes  []routeView
}

// Generate renders the gofmt'ed source of trilha_gen.go.
func Generate(res *scan.Result) ([]byte, error) {
	v := view{Result: res, Runtime: RuntimeImport}
	routes := append([]scan.Route{}, res.Routes...)
	sort.Slice(routes, func(i, j int) bool { return routes[i].Pattern < routes[j].Pattern })
	for _, r := range routes {
		v.Routes = append(v.Routes, routeView{Route: r, Alias: r.Alias})
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, v); err != nil {
		return nil, err
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("gen: formatting generated code: %w\n%s", err, buf.String())
	}
	return src, nil
}
